/**
 * MediaPipe Hand Landmarker wrapper (SOUP boundary, SRS-RHB-032): where the fingertips and palms are in the camera
 * image, for the stretch and massage guides. Loaded only when a hand exercise turns its camera on. Same rules as the
 * face engine (landmarker.ts): the WASM runtime from this app's origin, the model fetched as bytes and refused unless
 * its SHA-256 matches the pin (hand-model-lock.json, RM-H07). Nothing is stored.
 */
import { FilesetResolver, HandLandmarker } from '@mediapipe/tasks-vision';
import type { Vec2 } from '../core';
import { sha256Hex } from '../data/integrity';
import lock from './hand-model-lock.json';

export const HAND_MODEL = {
  name: lock.name,
  localPath: 'models/hand_landmarker.task',
  remoteUrl: lock.url,
  pinnedSha256: lock.sha256,
};

/** One detected hand: its 21 landmarks in video pixels (MediaPipe topology: 0 wrist, 4 thumb tip, 8 index tip, …). */
export interface DetectedHand {
  pts: Vec2[];
  score: number;
}

async function fetchHandModel(): Promise<Uint8Array> {
  try {
    const res = await fetch(new URL(HAND_MODEL.localPath, document.baseURI));
    const type = res.headers.get('content-type') ?? '';
    if (res.ok && !type.includes('text/html')) {
      const buf = new Uint8Array(await res.arrayBuffer());
      if (buf.byteLength > 1_000_000) return buf;
    }
  } catch {
    /* fall through to remote */
  }
  const res = await fetch(HAND_MODEL.remoteUrl);
  if (!res.ok) throw new Error(`hand model download failed (${res.status})`);
  return new Uint8Array(await res.arrayBuffer());
}

export class HandEngine {
  private lastTs = 0;

  private constructor(
    private readonly lm: HandLandmarker,
    readonly delegate: 'GPU' | 'CPU',
  ) {}

  static async create(): Promise<HandEngine> {
    const fileset = await FilesetResolver.forVisionTasks(new URL('mediapipe/wasm', document.baseURI).href);
    const bytes = await fetchHandModel();
    if ((await sha256Hex(bytes)) !== HAND_MODEL.pinnedSha256)
      throw new Error('MODEL_INTEGRITY: hand model hash does not match the validated build');
    const options = (delegate: 'GPU' | 'CPU') => ({
      baseOptions: { modelAssetBuffer: bytes, delegate },
      runningMode: 'VIDEO' as const,
      numHands: 2,
      minHandDetectionConfidence: 0.5,
      minHandPresenceConfidence: 0.5,
      minTrackingConfidence: 0.5,
    });
    try {
      return new HandEngine(await HandLandmarker.createFromOptions(fileset, options('GPU')), 'GPU');
    } catch {
      return new HandEngine(await HandLandmarker.createFromOptions(fileset, options('CPU')), 'CPU');
    }
  }

  /** The hands in the video's current frame, in video pixels (the same frame the face was found in). */
  detect(video: HTMLVideoElement): DetectedHand[] {
    const ts = Math.max(performance.now(), this.lastTs + 1);
    this.lastTs = ts;
    const r = this.lm.detectForVideo(video, ts);
    const w = video.videoWidth;
    const h = video.videoHeight;
    return r.landmarks.map((hand, k) => ({
      pts: hand.map((p) => ({ x: p.x * w, y: p.y * h })),
      score: r.handedness[k]?.[0]?.score ?? 0,
    }));
  }
}

let enginePromise: Promise<HandEngine> | null = null;

/** Lazily created singleton; a failed load can be retried. */
export function getHandEngine(): Promise<HandEngine> {
  if (!enginePromise) {
    enginePromise = HandEngine.create().catch((e: unknown) => {
      enginePromise = null;
      throw e;
    });
  }
  return enginePromise;
}
